## Submitted testbench
```systemverilog
module tb;

  // -------------------------------------------------------------
  // Parameters and clock generation
  // -------------------------------------------------------------
  localparam int CLK_PERIOD = 8;  // 125 MHz
  logic        clk = 0;
  always #(CLK_PERIOD/2) clk = ~clk;

  // -------------------------------------------------------------
  // DUT signals
  // -------------------------------------------------------------
  logic        rst;
  logic [15:0] prescale;
  logic        rxd;
  logic [7:0]  m_axis_tdata;
  logic        m_axis_tvalid;
  logic        m_axis_tready;
  logic        busy;
  logic        overrun_error;
  logic        frame_error;

  // -------------------------------------------------------------
  // DUT instantiation (uart_rx, default DATA_WIDTH = 8)
  // -------------------------------------------------------------
  uart_rx #(.DATA_WIDTH(8)) dut (
    .clk          (clk),
    .rst          (rst),
    .m_axis_tdata (m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd          (rxd),
    .busy         (busy),
    .overrun_error(overrun_error),
    .frame_error  (frame_error),
    .prescale     (prescale)
  );

  // Drive the always‑ready AXI stream handshake
  initial m_axis_tready = 1'b1;

  // -------------------------------------------------------------
  // Reset sequence
  // -------------------------------------------------------------
  initial begin
    rst = 1'b0;
    #200;
    rst = 1'b1;
    #200;
    rst = 1'b0;
    #200;
  end

  // Non‑zero prescale value (required for the glitch‑ignore condition)
  initial prescale = 16'd5;

  // -------------------------------------------------------------
  // Helper tasks
  // -------------------------------------------------------------
  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask

  // Send a UART frame (start‑bit + 8 data bits + stop‑bit) with an optional
  // glitch inserted on a selected data‑bit index (0‑based).  The glitch is a
  // toggle‑low‑high sequence that occurs while prescale_reg is non‑zero.
  task automatic send_frame_glitch(
    input byte unsigned data,
    input int       glitch_bit_index   // 0‑7
  );
    int bit_clks = prescale * 8;  // clocks per bit
    // ---- start bit -------------------------------------------------
    rxd = 1'b0;
    repeat (bit_clks) @(negedge clk);

    // ---- data bits -------------------------------------------------
    for (int i = 0; i < 8; i++) begin
      int expected = (data >> i) & 1'b1;
      if (i == glitch_bit_index) begin
        // hold the expected level for (bit_clks‑2) cycles
        repeat (bit_clks - 2) begin
          rxd = expected;
          @(negedge clk);
        end
        // toggle opposite
        rxd = ~expected;
        @(negedge clk);
        // toggle back to expected
        rxd = expected;
        @(negedge clk);
      end else begin
        repeat (bit_clks) begin
          rxd = expected;
          @(negedge clk);
        end
      end
    end

    // ---- stop bit ---------------------------------------------------
    rxd = 1'b1;
    repeat (bit_clks) @(negedge clk);
  endtask

  // -------------------------------------------------------------
  // Test sequence
  // -------------------------------------------------------------
  initial begin
    // First frame: 0xA5 with a glitch on data‑bit 2
    send_frame_glitch(8'hA5, 2);
    // Gap between frames (≈2 µs as in the reference tests)
    #2000;
    // Second frame: 0x5A with a glitch on data‑bit 3
    send_frame_glitch(8'h5A, 3);
    // Allow enough time for the coverage model to evaluate the hit
    #5000;
    $finish;
  end

endmodule
```

